def test_flex_direction_alternating_with_percent():
    config = Config()
    root = Node(config)
    root.position_type = PositionType.ABSOLUTE
    root.width = 200
    root.height = 300
    root_child0 = Node(config)
    root_child0.flex_direction = FlexDirection.ROW
    root_child0.set_position(Edge.LEFT, "10%")
    root_child0.set_position(Edge.TOP, "10%")
    root_child0.width = "50%"
    root_child0.height = "50%"
    root.insert_child(root_child0, 0)
    root.calculate_layout(None, None, Direction.LTR)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(200, abs=1e-4)
    assert root.layout.height == pytest.approx(300, abs=1e-4)
    assert root_child0.layout.left == pytest.approx(20, abs=1e-4)
    assert root_child0.layout.top == pytest.approx(30, abs=1e-4)
    assert root_child0.layout.width == pytest.approx(100, abs=1e-4)
    assert root_child0.layout.height == pytest.approx(150, abs=1e-4)
    root.calculate_layout(None, None, Direction.RTL)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(200, abs=1e-4)
    assert root.layout.height == pytest.approx(300, abs=1e-4)
    assert root_child0.layout.left == pytest.approx(120, abs=1e-4)
    assert root_child0.layout.top == pytest.approx(30, abs=1e-4)
    assert root_child0.layout.width == pytest.approx(100, abs=1e-4)
    assert root_child0.layout.height == pytest.approx(150, abs=1e-4)
